        R"TVHTML(
<section class="hero"><div><div class="eyebrow"><span class="dot"></span>LIVE TV · TRÊN ROBOT CỦA BẠN</div><h1>Mọi kênh yêu thích.<br><span>Trong tầm tay.</span></h1><p class="intro">Chọn một kênh, để robot mang thế giới đến gần hơn. Hình trên TFT, âm thanh qua loa robot.</p></div><article class="hero-art" aria-label="Trạng thái phát"><div class="orb"></div><div class="player-top"><span>TRUYỀN HÌNH TRÊN ROBOT</span><span class="live-badge"><span class="dot"></span><span id="playerBadge">SẴN SÀNG</span></span></div><div class="player-body"><span class="screen-icon"><svg><use href="#i-tv"/></svg></span><div><h2 id="playingTitle">Sẵn sàng lên sóng</h2><p id="playingState">Chọn một kênh để bắt đầu</p></div></div><div class="player-foot"><span class="signal"><svg><use href="#i-wave"/></svg><span id="quality">240 × 240 · tối đa 12 fps</span></span><button id="stopBtn" class="stop" onclick="stopTv()" disabled><svg><use href="#i-stop"/></svg>Dừng phát</button></div></article></section>
<section aria-label="Danh sách kênh"><div class="toolbar"><div class="section-title"><h2>Khám phá kênh</h2><p id="channelCount">Danh sách được lưu trên MCP server</p></div><div class="tools"><label class="search"><svg><use href="#i-search"/></svg><span class="sr-only">Tìm kênh</span><input id="search" placeholder="Tìm tên kênh hoặc bí danh…" maxlength="128" oninput="searchChanged()"></label><button class="icon-button" data-remote onclick="loadList()" aria-label="Tải lại danh sách"><svg><use href="#i-refresh"/></svg></button><button class="primary" data-remote onclick="newChannel()"><svg><use href="#i-plus"/></svg>Thêm kênh</button></div></div><div id="toast" class="toast hidden" role="status" aria-live="polite"></div><div id="channels" class="grid"><div class="empty"><h3>Đang tải danh sách…</h3><p>Kết nối tới thư viện kênh của bạn.</p></div></div><div class="pager"><button id="prev" data-remote onclick="changePage(-1)" disabled>← Trang trước</button><span id="pageInfo">Trang 1</span><button id="next" data-remote onclick="changePage(1)" disabled>Trang sau →</button></div></section>
<footer class="bottom-note"><span><svg><use href="#i-tv"/></svg>Điều khiển từ đây. Trải nghiệm trên robot.</span><span>Chạm đôi cảm biến để dừng TV bất cứ lúc nào.</span></footer></main>
<dialog id="editor"><form id="editForm" onsubmit="saveChannel(event)"><div class="dialog-heading"><h2 id="editorTitle">Thêm kênh mới</h2><button type="button" class="icon-button" aria-label="Đóng" onclick="closeEditor()">✕</button></div><div class="field"><label for="name">Tên kênh</label><input id="name" required maxlength="128" placeholder="Ví dụ: HTV9"><small>Tên này xuất hiện trên màn hình TFT của robot.</small></div><div class="field"><label for="url">URL HLS</label><input id="url" type="url" required maxlength="2048" placeholder="https://…/playlist.m3u8"><small>Nguồn cần truy cập được từ VPS và có cả hình lẫn tiếng.</small></div><div class="fields"><div class="field"><label for="aliases">Tên gọi khác</label><input id="aliases" placeholder="HTV 9, Đài HTV9"><small>Ngăn cách bằng dấu phẩy, tối đa 5 bí danh.</small></div><div class="field"><label for="order">Thứ tự</label><input id="order" type="number" min="0" max="999" value="0"></div></div><label class="check"><input id="enabled" type="checkbox" checked>Cho phép phát và tìm kênh qua hội thoại</label><p id="editorMessage" class="modal-message" role="status"></p><div class="dialog-foot"><button type="button" class="secondary" data-remote onclick="checkSource()">Kiểm tra nguồn</button><button type="button" class="secondary" onclick="closeEditor()">Hủy</button><button type="submit" class="primary" data-remote>Lưu kênh</button></div></form></dialog>
<dialog id="deleteDialog"><div class="dialog-heading"><h2>Xóa kênh này?</h2></div><p id="deleteMessage" class="modal-message"></p><div class="dialog-foot"><button class="secondary" onclick="$('deleteDialog').close()">Giữ lại</button><button class="danger" data-remote onclick="deleteChannel()">Xóa kênh</button></div></dialog>
<script>
const $=id=>document.getElementById(id),icon=id=>'<svg aria-hidden="true"><use href="#i-'+id+'"/></svg>';let page=0,total=0,hasMore=false,busy=false,statusBusy=false,editing=null,deleting=null,items=[],current={},searchTimer,catalogLoaded=false;
async function api(path,body){const r=await fetch(path,{cache:'no-store',...(body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})});let d;try{d=await r.json()}catch{throw Error('Robot chưa trả lời. Hãy kiểm tra kết nối.')}if(!r.ok||d.ok===false)throw Error(d.error||'Yêu cầu chưa thành công');return d}
function say(text,error=false){$('toast').textContent=text;$('toast').className='toast'+(error?' error':'');}
function buttons(){document.querySelectorAll('[data-remote]').forEach(b=>b.disabled=busy);$('prev').disabled=busy||page===0;$('next').disabled=busy||!hasMore;paintPlaying();}
async function remote(fn){if(busy)return;busy=true;buttons();try{return await fn()}catch(e){say(e.message,true);if($('editor').open)$('editorMessage').textContent=e.message;}finally{busy=false;buttons()}}
function empty(title,message){const box=document.createElement('div');box.className='empty';const h=document.createElement('h3'),p=document.createElement('p');h.textContent=title;p.textContent=message;box.append(h,p);$('channels').replaceChildren(box)}
function render(){if(!items.length){empty($('search').value?'Chưa tìm thấy kênh':'Thư viện đang chờ lên sóng',$('search').value?'Thử tên ngắn hơn hoặc bí danh khác.':'Thêm kênh HLS đầu tiên để bắt đầu xem TV.');return}const nodes=items.map((item,index)=>{const card=document.createElement('article');card.className='channel';card.dataset.id=item.id;card.style.setProperty('--tint',['#8d5db640','#3a83a840','#b36d7140','#627e4940','#5573b440','#a36d3f40'][index%6]);card.innerHTML='<div class="channel-top"><span class="channel-number"></span><span class="channel-monogram"></span><span class="channel-state"></span></div><div class="channel-content"><h3 class="channel-name"></h3><p class="channel-type">Truyền hình trực tiếp · HLS</p><div class="channel-actions"><button class="play" data-remote>'+icon('play')+' <span>Phát trên robot</span></button><button class="edit" data-remote aria-label="Sửa kênh">'+icon('edit')+'</button><button class="delete" data-remote aria-label="Xóa kênh">'+icon('trash')+'</button></div></div>';card.querySelector('.channel-number').textContent=String(page*10+index+1).padStart(2,'0');card.querySelector('.channel-monogram').textContent=item.name.length<=12?item.name:item.name.split(/\s+/).map(x=>x[0]).join('').slice(0,5).toUpperCase();card.querySelector('.channel-name').textContent=item.name;card.querySelector('.channel-name').title=item.name;card.querySelector('.play').onclick=()=>playChannel(item);card.querySelector('.edit').onclick=()=>editChannel(item);card.querySelector('.delete').onclick=()=>confirmDelete(item);return card});$('channels').replaceChildren(...nodes);paintPlaying();}
function paintPlaying(){document.querySelectorAll('.channel').forEach(card=>{const item=items.find(x=>x.id===card.dataset.id),active=current.active&&current.channel_id===item.id;card.classList.toggle('is-playing',!!active);card.querySelector('.channel-state').textContent=active?'ĐANG PHÁT':item.enabled?'LIVE':'ĐANG TẮT';card.querySelector('.play').disabled=busy||!item.enabled;card.querySelector('.play span').textContent=active?'Phát lại':'Phát trên robot';})}
async function loadList(){if(busy){clearTimeout(searchTimer);searchTimer=setTimeout(loadList,400);return}await remote(async()=>{const data=await api('/api/tv/channels?query='+encodeURIComponent($('search').value.trim())+'&page='+page);catalogLoaded=true;items=data.items;total=data.total;hasMore=data.has_more;$('channelCount').textContent=total+' kênh trong thư viện · Quản lý từ một nơi';$('pageInfo').textContent='Trang '+(page+1)+' / '+Math.max(1,Math.ceil(total/10));render();});if(!catalogLoaded)empty("Chưa tải được thư viện","Kiểm tra MCP hoặc bấm tải lại danh sách.");paintPlaying()}
function searchChanged(){page=0;clearTimeout(searchTimer);searchTimer=setTimeout(loadList,350)}function changePage(delta){page+=delta;loadList()}
async function getStatus(){if(statusBusy||document.hidden)return;statusBusy=true;try{current=await api('/api/tv/status');const labels={starting:'Đang mở kênh…',playing:'Đang phát trên TFT và loa robot',reconnecting:'Đang kết nối lại nguồn…',stopped:'Chọn một kênh để bắt đầu',error:'Chưa phát được kênh'};$('playerBadge').textContent=current.state==='playing'?'LIVE':current.active?'ĐANG MỞ':'SẴN SÀNG';$('playingTitle').textContent=current.active?(current.title||'Live TV'):'Sẵn sàng lên sóng';$('playingState').textContent=current.error||labels[current.state]||'Đang chờ';$('quality').textContent=current.active&&current.fps>0?'240 × 240 · '+current.fps.toFixed(1)+' fps':'240 × 240 · tối đa 12 fps';$('stopBtn').disabled=!current.active;$('connection').className='connection'+(current.server_connected?' online':'');$('connectionText').textContent=current.server_connected?'MCP Online':'MCP chưa kết nối';paintPlaying()}catch{$('connection').className='connection';$('connectionText').textContent='Robot mất kết nối'}finally{statusBusy=false}}
async function playChannel(item){await remote(async()=>{say('Đang mở '+item.name+'…');await api('/api/tv/play',{id:item.id});say('Robot đã nhận yêu cầu. Đang chờ hình và tiếng.');await getStatus()})}
async function stopTv(){try{await api('/api/tv/stop',{});say('Đã gửi lệnh dừng trên robot.');await getStatus()}catch(e){say(e.message,true)}}
function newChannel(){editing=null;$('editForm').reset();$('order').value=total;$('enabled').checked=true;$('editorTitle').textContent='Thêm kênh mới';$('editorMessage').textContent='';$('editor').showModal();$('name').focus()}
function closeEditor(){if(!busy)$('editor').close()}
async function editChannel(item){await remote(async()=>{editing=await api('/api/tv/channel?id='+encodeURIComponent(item.id));$('editorTitle').textContent='Chỉnh sửa kênh';$('name').value=editing.name;$('url').value=editing.url;$('aliases').value=editing.aliases.join(', ');$('order').value=editing.order;$('enabled').checked=editing.enabled;$('editorMessage').textContent='Tên và URL mới áp dụng ở lần phát tiếp theo.';$('editor').showModal()})}
async function checkSource(){if(!$('url').reportValidity())return;await remote(async()=>{$('editorMessage').textContent='Đang kiểm tra nguồn từ VPS…';const data=await api('/api/tv/check',{url:$('url').value.trim()});$('editorMessage').textContent=data.message})}
async function saveChannel(event){event.preventDefault();let saved=false;await remote(async()=>{const channel={...(editing?{id:editing.id,version:editing.version}:{}),name:$('name').value.trim(),url:$('url').value.trim(),aliases:$('aliases').value.split(',').map(s=>s.trim()).filter(Boolean),order:Number($('order').value),enabled:$('enabled').checked};await api('/api/tv/channel',{channel});saved=true;say('Đã lưu kênh trên MCP server.');$('editor').close()});if(saved)await loadList()}
function confirmDelete(item){deleting=item;$('deleteMessage').textContent='Xóa “'+item.name+'” khỏi thư viện? Nếu kênh đang phát, phiên TV sẽ được dừng.';$('deleteDialog').showModal()}
async function deleteChannel(){let deleted=false;await remote(async()=>{await api('/api/tv/channel/delete',{id:deleting.id,version:deleting.version});deleted=true;$('deleteDialog').close();say('Đã xóa kênh.');});if(deleted){if(items.length===1&&page>0)page--;await loadList();await getStatus()}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)getStatus()});loadList();getStatus();setInterval(getStatus,1500);
</script></body></html>)TVHTML";
